insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_53_v1'
from (values
('127.299.d.1.A',3,'A new juice bar closed after eight months. Which finding is most likely to explain its failure?','["Rent and supplies cost more than its sales brought in", "The owner posted on social media", "The menu was printed in color", "The shop had too many happy customers"]'::jsonb,0,'Failed businesses often run out of cash when costs exceed income.','original'),
('127.299.d.1.A',4,'Studying why many start-ups fail helps an entrepreneur to:','["Skip a business plan", "Avoid repeating common mistakes such as poor planning", "Ignore customers", "Guarantee a profit"]'::jsonb,1,'Learning from failures reduces risk.','original'),
('127.299.d.1.B',3,'Which is a financial risk faced by an entrepreneur?','["Choosing a logo", "Having a busy schedule", "Losing personal savings invested in the business", "Meeting new people"]'::jsonb,2,'Owners often put their own money at risk.','original'),
('127.299.d.1.B',4,'An entrepreneur who borrows heavily to open a store faces the risk of:','["Avoiding all competition", "Paying no interest", "Receiving free inventory", "Being unable to repay the loan if sales are low"]'::jsonb,3,'Debt must be repaid regardless of sales.','original'),
('127.299.d.1.C',3,'Before launching a food truck, an entrepreneur weighs possible profit against possible loss. This is comparing:','["Risk versus opportunity", "Price versus weather", "Style versus color", "Hours versus holidays"]'::jsonb,0,'Entrepreneurs evaluate risk and reward.','original'),
('127.299.d.1.C',4,'A business with high startup costs but strong demand offers:','["No risk", "Large opportunity along with significant risk", "No opportunity", "Guaranteed success"]'::jsonb,1,'Reward and risk often rise together.','original'),
('127.299.d.1.D',3,'Compared with an employee, an entrepreneur usually has:','["No decisions to make", "A guaranteed paycheck", "More control over decisions and more responsibility for results", "No responsibility"]'::jsonb,2,'Owners decide and bear the outcome.','original'),
('127.299.d.1.D',4,'Which is a typical difference between owning a business and working for one?','["Employees set company policy alone", "Owners always work fewer hours", "Employees pay all business bills", "Owners earn income only after expenses are paid"]'::jsonb,3,'Owners are paid from profit after expenses.','original'),
('127.299.d.1.E',3,'A person with strong self-motivation, creativity, and comfort with risk shows:','["Aptitude for entrepreneurship", "Weak planning", "No interest in business", "A lack of skills"]'::jsonb,0,'These traits fit entrepreneurs.','original'),
('127.299.d.1.E',4,'A self-assessment shows a student dislikes uncertainty and prefers steady pay. This suggests the student might:','["Be sure to succeed as an owner", "Be better suited to a stable employee role than owning a start-up", "Have no skills", "Need no income"]'::jsonb,1,'Personality fit matters.','original'),
('127.299.d.1.F',3,'An entrepreneur who tracks income and expenses each month is:','["Ignoring customers", "Avoiding taxes", "Managing the organization''s finances", "Wasting time"]'::jsonb,2,'Record keeping is basic financial management.','original'),
('127.299.d.1.F',4,'Why must an owner manage cash flow carefully?','["Bills are optional", "Customers pay in advance always", "Cash flow does not matter", "Bills come due even when customers have not yet paid"]'::jsonb,3,'Timing of cash determines whether bills can be paid.','original'),
('127.299.d.1.G',3,'A calculated risk is one that an entrepreneur takes after:','["Researching the possible outcomes", "Flipping a coin", "Copying a rumor", "Ignoring information"]'::jsonb,0,'Calculated risks are informed risks.','original'),
('127.299.d.1.G',4,'Which action shows a sound approach to risk-taking?','["Spending all savings on day one", "Testing a product with a small group before a full launch", "Skipping research", "Copying a competitor without thought"]'::jsonb,1,'Small tests limit risk.','original'),
('127.299.d.1.H',3,'A competitive advantage is something that lets a business:','["Skip marketing", "Charge any price", "Do better than its competitors in a way customers value", "Avoid taxes"]'::jsonb,2,'Advantages set a business apart.','original'),
('127.299.d.1.H',4,'A shop that offers same-day repair when rivals take a week has a competitive advantage in:','["Price only", "Product color only", "Location only", "Speed of service"]'::jsonb,3,'Faster service is a differentiator.','original'),
('127.299.d.1.I',3,'Interviewing a local business owner is useful because the owner can describe:','["The real risks and rewards of ownership", "Last night''s game", "Weather", "Gossip"]'::jsonb,0,'First-hand experience informs students.','original'),
('127.299.d.1.I',4,'Before an interview with an owner, a student should:','["Skip taking notes", "Prepare thoughtful questions", "Ask only about gossip", "Show up unprepared"]'::jsonb,1,'Preparation shows respect.','original'),
('127.299.d.1.J',3,'Psychology helps an entrepreneur understand customers by explaining:','["Tax law", "Shipping routes", "Why people choose or avoid a product", "Weather patterns"]'::jsonb,2,'Motives and feelings drive choices.','original'),
('127.299.d.1.J',4,'Sociology helps explain customer behavior by studying how:','["Taxes are filed", "Machines are fixed", "Prices are calculated", "Groups, culture, and peers influence buying"]'::jsonb,3,'Social influences shape demand.','original'),
('127.299.d.2.A',3,'Which is a basic type of business formation?','["Sole proprietorship", "Weather station", "Shipping lane", "Union card"]'::jsonb,0,'Sole proprietorship, partnership, and corporation are basic forms.','original'),
('127.299.d.2.B',3,'A benefit of a sole proprietorship is that it:','["Pays no taxes", "Is simple and inexpensive to start", "Protects personal assets from all debts", "Has unlimited investors"]'::jsonb,1,'Simple setup is an advantage.','original'),
('127.299.d.2.B',4,'A drawback of a sole proprietorship is that the owner:','["Has no control", "Cannot hire staff", "Is personally liable for business debts", "Cannot earn profit"]'::jsonb,2,'Unlimited personal liability is a major drawback.','original'),
('127.299.d.2.C',3,'If a sole proprietor''s business is sued and loses, the owner''s personal property may be:','["Taxed less", "Doubled", "Fully protected", "At risk to pay the judgment"]'::jsonb,3,'Owners are personally liable.','original'),
('127.299.d.2.C',4,'A limited liability company generally protects owners by:','["Limiting personal responsibility for business debts", "Requiring no records", "Preventing profit", "Eliminating all taxes"]'::jsonb,0,'LLCs separate personal and business liability.','original'),
('127.299.d.3.A',3,'A business plan''s operations section lists the materials, facilities, and:','["Hobbies", "Personnel needed to run the business", "Favorite songs", "Weather"]'::jsonb,1,'Operations describe resources.','original'),
('127.299.d.3.A',4,'A start-up bakery''s technology needs might include:','["A typewriter only", "A canoe", "A point-of-sale system", "A telescope"]'::jsonb,2,'Operations include technology.','original'),
('127.299.d.3.B',3,'A timeline of tasks for opening a business shows:','["Only the logo", "Only the profits", "Only the staff", "What must be done and by when"]'::jsonb,3,'Timelines sequence tasks.','original'),
('127.299.d.3.B',4,'Obtaining a permit before opening day is an example of a task with a:','["Deadline that depends on approval time", "Cost of zero", "Random date", "Unlimited timeframe"]'::jsonb,0,'Approvals affect schedules.','original'),
('127.299.d.3.C',3,'Which is a start-up cost an owner must list?','["Hobbies", "Equipment and initial inventory", "Opinions", "Weather"]'::jsonb,1,'Start-up costs include assets.','original'),
('127.299.d.3.C',4,'Wages and salaries for employees are part of a business''s:','["Revenue", "Profit", "Ongoing operating costs", "Loan interest only"]'::jsonb,2,'Payroll is an operating expense.','original'),
('127.299.d.3.D',3,'Rent, utilities, and insurance are examples of:','["Revenue", "Savings", "Profit", "Costs of operating a business"]'::jsonb,3,'Operating costs recur.','original'),
('127.299.d.3.D',4,'Analyzing monthly costs helps an owner decide:','["Where spending can be reduced", "Who to hire as a friend", "Which holiday to take", "What color to paint"]'::jsonb,0,'Cost analysis finds savings.','original'),
('127.299.d.3.E',3,'Estimating how much money is needed on hand to operate a business helps avoid:','["Hiring staff", "Running out of cash", "Paying taxes", "Making sales"]'::jsonb,1,'Working capital prevents cash shortages.','original'),
('127.299.d.3.E',4,'A new store expects $4,000 in monthly costs and no sales for the first two months. Cash needed to cover those months is about:','["$16,000", "$2,000", "$8,000", "$4,000"]'::jsonb,2,'4,000 x 2 = 8,000.','original'),
('127.299.d.3.F',3,'Seeking advice from an industry mentor helps an entrepreneur:','["Avoid planning", "Ignore customers", "Skip research", "Learn from real experience"]'::jsonb,3,'Mentors share practical wisdom.','original'),
('127.299.d.3.F',4,'Reviewing an actual business case with a mentor can help an owner analyze:','["Real decisions and their results", "Weather", "Fictional stories only", "Music"]'::jsonb,0,'Case review builds judgment.','original'),
('127.299.d.3.G',3,'An income statement shows a business''s:','["Weather", "Revenue, expenses, and profit over a period", "Employee birthdays", "Store hours"]'::jsonb,1,'It summarizes performance.','original'),
('127.299.d.3.G',4,'Comparing financial statements month to month helps an owner:','["Avoid planning", "Hide losses", "Spot trends and ways to improve profit", "Skip taxes"]'::jsonb,2,'Trends guide decisions.','original'),
('127.299.d.3.H',3,'Cash burn is the rate at which a business:','["Hires staff", "Earns profit", "Collects tax", "Spends its cash reserves"]'::jsonb,3,'Burn measures cash outflow.','original'),
('127.299.d.3.H',4,'A start-up with $60,000 in cash that spends $10,000 more than it earns each month has about how many months before it runs out?','["6 months", "10 months", "60 months", "3 months"]'::jsonb,0,'60,000 / 10,000 = 6.','original'),
('127.299.d.4.A',3,'A business contributes to the economic well-being of a community by:','["Avoiding customers", "Creating jobs and paying local taxes", "Closing early", "Raising unemployment"]'::jsonb,1,'Jobs and taxes support communities.','original'),
('127.299.d.4.A',4,'A new factory in a small town can help local stores by:','["Removing jobs", "Closing roads", "Increasing the number of customers with paychecks", "Lowering wages to zero"]'::jsonb,2,'Employment boosts spending.','original'),
('127.299.d.4.B',3,'A business can ensure economic stability by:','["Spending all income at once", "Ignoring costs", "Relying on one customer only", "Planning finances and diversifying its customers"]'::jsonb,3,'Planning supports stability.','original'),
('127.299.d.4.B',4,'Relying on one large customer for most sales is risky because:','["Losing that customer could cause a major drop in income", "It guarantees growth", "It reduces costs", "It removes competition"]'::jsonb,0,'Diversification protects stability.','original'),
('127.299.d.4.C',3,'A business owner is responsible for providing:','["Free products to all", "A safe workplace for employees and customers", "A swimming pool", "Unlimited breaks"]'::jsonb,1,'Safety is a legal responsibility.','original'),
('127.299.d.4.C',4,'A restaurant must follow health codes to protect:','["The menu font", "Advertising", "Customers from foodborne illness", "The parking lot"]'::jsonb,2,'Health regulations protect the public.','original'),
('127.299.d.4.D',3,'A business investing in its community might:','["Avoid hiring locally", "Pollute local streams", "Ignore local needs", "Sponsor a local youth team"]'::jsonb,3,'Community investment builds goodwill.','original'),
('127.299.d.4.D',4,'Which action is an example of a business investing in community development?','["Funding scholarships for local students", "Raising prices", "Closing a store", "Cutting wages"]'::jsonb,0,'Scholarships invest in people.','original'),
('127.299.d.5.A',3,'A growth strategy in which a business opens more locations is called:','["Liquidation", "Expansion", "Dissolution", "Downsizing"]'::jsonb,1,'Adding locations expands the business.','original'),
('127.299.d.5.A',4,'Which growth strategy may be most feasible for a small shop with limited cash?','["Opening ten stores at once", "Buying a competitor", "Selling products online to reach more customers", "Building a factory"]'::jsonb,2,'Online sales grow reach at low cost.','original'),
('127.299.d.5.B',3,'One way an owner can get financial support to grow is by:','["Quitting", "Ignoring costs", "Printing money", "Applying for a bank loan"]'::jsonb,3,'Loans provide capital.','original'),
('127.299.d.5.B',4,'An investor who gives money in exchange for part ownership is providing:','["Equity financing", "Insurance", "Free services", "Debt financing"]'::jsonb,0,'Equity trades ownership for funds.','original'),
('127.299.d.5.C',3,'One way to determine what a business is worth is to look at its:','["Store smell", "Assets, earnings, and market conditions", "Owner''s age", "Logo color"]'::jsonb,1,'Valuation uses financial data.','original'),
('127.299.d.5.C',4,'A buyer values a business partly by how much profit it earns because:','["Profit hides risk", "Profit is illegal", "Profit shows what the business may earn in the future", "Profit is random"]'::jsonb,2,'Earnings suggest future returns.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_53_v1'
from (values
('127.299.d.5.D',3,'One path for exiting a business is to:','["Hire a mascot", "Ignore it", "Raise debt", "Sell it to another owner"]'::jsonb,3,'Selling is a common exit.','original'),
('127.299.d.5.D',4,'Passing a family business to the next generation is an example of a:','["Succession exit", "Bankruptcy", "Merger", "Franchise"]'::jsonb,0,'Succession transfers ownership within a family.','original'),
('127.299.d.5.E',3,'Before preparing to sell a business, an owner should have:','["Only verbal agreements", "Organized financial records", "Missing receipts", "No records"]'::jsonb,1,'Buyers want clear records.','original'),
('127.299.d.5.E',4,'A factor that can raise a business''s sale value is:','["Unclear ownership", "Lost customers", "Steady, documented profits", "Unpaid taxes"]'::jsonb,2,'Documented earnings add value.','original'),
('127.299.d.6.A',3,'To research a problem at a real work site, a student should first:','["Blame workers", "Guess", "Ignore it", "Observe operations and gather facts"]'::jsonb,3,'Observation reveals problems.','original'),
('127.299.d.6.A',4,'A student notices long customer waits at a cafe. A good first research step is to:','["Track wait times at different hours", "Remove the counter", "Cut staff", "Ignore it"]'::jsonb,0,'Data clarifies the issue.','original'),
('127.299.d.6.B',3,'Researching how to resolve a business problem includes:','["Avoiding experts", "Comparing possible solutions", "Ignoring cost", "Choosing the first idea"]'::jsonb,1,'Compare options before choosing.','original'),
('127.299.d.6.B',4,'A report on a business problem should include the problem, evidence, and:','["A rumor", "A slogan", "Recommended solutions", "A joke"]'::jsonb,2,'Reports recommend action.','original'),
('127.299.d.6.C',3,'A proposal for future business opportunities should describe:','["Hobbies", "Birthdays", "Weather", "The opportunity, the cost, and expected benefits"]'::jsonb,3,'Proposals justify action.','original'),
('127.299.d.6.C',4,'Which detail most strengthens a proposal to a business owner?','["Evidence that customers want the new service", "A longer font", "Fancy borders only", "A louder voice"]'::jsonb,0,'Evidence persuades.','original'),
('127.299.d.6.D',3,'An alliance with another business can help by:','["Cutting all ties", "Sharing resources and customers", "Hiding information", "Raising conflict"]'::jsonb,1,'Alliances create mutual benefits.','original'),
('127.299.d.6.D',4,'A coffee shop and a bakery cross-promote each other''s products. This is an example of:','["A monopoly", "Price fixing", "A business alliance", "A merger"]'::jsonb,2,'Cross-promotion is an alliance.','original'),
('127.300.d.1.A',3,'A start-up founder explains a new idea to a mentor. Clear communication includes:','["Using only jargon", "Skipping details", "Speaking too quietly to hear", "Stating the idea simply and backing it with examples"]'::jsonb,3,'Clarity helps listeners understand.','original'),
('127.300.d.1.A',4,'A founder sends investors a one-page summary with a simple graph. This is an example of using:','["Written and visual communication together", "Only silence", "Only a phone call", "Only rumors"]'::jsonb,0,'Combining media supports understanding.','original'),
('127.300.d.1.B',3,'A client explains what they want built. Which action shows active listening?','["Finishing their sentences", "Taking notes and asking follow-up questions", "Checking your phone", "Changing the subject"]'::jsonb,1,'Note-taking and questions clarify needs.','original'),
('127.300.d.1.B',4,'A founder repeats back a customer''s request to be sure it is right. This technique is called:','["Interrupting", "Daydreaming", "Paraphrasing to confirm understanding", "Ignoring"]'::jsonb,2,'Restating verifies meaning.','original'),
('127.300.d.1.C',3,'A pitch to a small group of friends about a new app is best delivered as an:','["Legal hearing", "Press conference", "Formal board meeting", "Informal presentation"]'::jsonb,3,'Casual settings suit informal talks.','original'),
('127.300.d.1.C',4,'For a formal investor presentation, a founder should:','["Rehearse and organize the talk with clear sections", "Read every word aloud", "Wing it", "Skip the closing"]'::jsonb,0,'Preparation improves delivery.','original'),
('127.300.d.1.D',3,'A founder reviews sales data and tells the team what it means. This is:','["Hiding results", "Analyzing and communicating information", "Guessing", "Ignoring numbers"]'::jsonb,1,'Interpretation turns data into insight.','original'),
('127.300.d.1.D',4,'After analyzing survey results, the most useful message to a team is:','["Only the highest score", "A joke", "The key finding and what action to take", "All raw data without comment"]'::jsonb,2,'Messages should lead to action.','original'),
('127.300.d.1.E',3,'A positive way to handle a client who is upset about late delivery is to:','["Blame them", "Argue", "Hang up", "Listen, apologize, and offer a solution"]'::jsonb,3,'Respectful service retains clients.','original'),
('127.300.d.1.E',4,'Following up with a client after a project to ask for feedback helps:','["Maintain a strong relationship", "Raise complaints", "Avoid improvement", "End the relationship"]'::jsonb,0,'Follow-up shows care.','original'),
('127.300.d.2.A',3,'A founder facing a drop in sales studies the data before choosing a response. This is:','["Ignoring facts", "Critical thinking", "Guessing", "Panicking"]'::jsonb,1,'Critical thinking uses evidence.','original'),
('127.300.d.2.A',4,'A team debates two product ideas and compares evidence for each. This shows critical thinking in a:','["Solo guess", "Coin flip", "Group setting", "Random vote"]'::jsonb,2,'Groups can weigh evidence together.','original'),
('127.300.d.2.B',3,'To gather information for a decision about a supplier, a founder could:','["Use the first result", "Ask nobody", "Pick randomly", "Compare prices, reviews, and delivery times"]'::jsonb,3,'Research informs choices.','original'),
('127.300.d.2.B',4,'A founder wants to know whether customers will buy a product. A technical research step is to:','["Run a small survey or test sale", "Copy a rival''s ad", "Wait", "Assume yes"]'::jsonb,0,'Testing gives evidence.','original'),
('127.300.d.2.C',3,'A start-up''s packaging costs too much. A creative solution might be to:','["Stop shipping", "Redesign the package with cheaper recyclable materials", "Raise every price", "Hide the product"]'::jsonb,1,'Innovation can cut costs.','original'),
('127.300.d.2.C',4,'Breaking a problem like slow shipping into causes such as packing, carrier, and address errors is:','["Avoiding the issue", "Ignoring customers", "Analyzing the elements of the problem", "Blaming the carrier only"]'::jsonb,2,'Analysis isolates causes.','original'),
('127.300.d.3.A',3,'A workshop where a founder sells products should have:','["Blocked doors", "Loose cords everywhere", "No fire extinguisher", "Clear exits and safety rules posted"]'::jsonb,3,'Safety rules protect people.','original'),
('127.300.d.3.A',4,'An entrepreneur who trains workers on safe equipment use is:','["Following workplace safety rules consistently", "Breaking policy", "Wasting time", "Avoiding duty"]'::jsonb,0,'Training prevents injury.','original'),
('127.300.d.3.B',3,'An online store should protect customer data by:','["Sharing logins", "Using secure passwords and encrypted payment systems", "Posting card numbers", "Using weak passwords"]'::jsonb,1,'Security protects customers.','original'),
('127.300.d.3.B',4,'A start-up employee receives an email asking for account passwords. Cybersecurity policy says to:','["Forward it to everyone", "Click the link", "Report it as suspected phishing", "Reply with the password"]'::jsonb,2,'Phishing must be reported.','original'),
('127.300.d.4.A',3,'A supplier offers a hidden kickback for placing a large order. An ethical entrepreneur should:','["Ask for more", "Accept it quietly", "Share it with friends", "Decline it and keep the deal honest"]'::jsonb,3,'Kickbacks are unethical.','original'),
('127.300.d.4.A',4,'When two choices are legal but one is more honest, an entrepreneur committed to ethics will:','["Choose the more honest choice", "Choose the secret one", "Choose randomly", "Choose the cheaper one"]'::jsonb,0,'Ethics go beyond bare legality.','original'),
('127.300.d.4.B',3,'A founder realizes a product has a safety flaw but a recall will cost money. Integrity says to:','["Blame customers", "Notify customers and fix the problem", "Hide the flaw", "Wait for complaints"]'::jsonb,1,'Safety comes before profit.','original'),
('127.300.d.4.B',4,'A founder who keeps a promise to a customer even when it costs the company shows:','["Poor planning", "Carelessness", "Integrity", "Weakness"]'::jsonb,2,'Integrity means doing right despite cost.','original'),
('127.300.d.4.C',3,'A food business must follow health inspection rules. This is an example of complying with:','["Fashion trends", "Music laws", "Sports rules", "Regulations for its industry"]'::jsonb,3,'Industry regulations apply to specific businesses.','original'),
('127.300.d.4.C',4,'An entrepreneur selling online must follow laws about:','["Truthful advertising and collecting sales tax", "Parking only", "Weather reports", "School grades"]'::jsonb,0,'E-commerce has legal duties.','original'),
('127.300.d.5.A',3,'A supervised entrepreneurship experience should include:','["No records", "A record of activities and what was learned", "Only grades", "Only photos"]'::jsonb,1,'Documentation shows learning.','original'),
('127.300.d.5.A',4,'A student writes a weekly reflection on a pop-up shop experience. This is:','["Cheating", "Wasting time", "Evaluating a learning activity", "Advertising"]'::jsonb,2,'Reflection evaluates learning.','original'),
('127.300.d.5.B',3,'Advanced technical skills for an entrepreneur might include:','["Doing no research", "Ignoring tools", "Copying a template blindly", "Building a basic online store or budget model"]'::jsonb,3,'Technical skills support the business.','original'),
('127.300.d.5.B',4,'To deepen technical knowledge, a student could:','["Shadow an owner during bookkeeping tasks", "Avoid new tasks", "Skip training", "Refuse feedback"]'::jsonb,0,'Observation builds skill.','original'),
('127.300.d.5.C',3,'Information technology tools a small business may use to manage work include:','["A paper map only", "Accounting and scheduling software", "Carbon paper", "A telegraph"]'::jsonb,1,'IT tools improve efficiency.','original'),
('127.300.d.5.C',4,'Inventory software helps a shop to:','["Hide products", "Raise prices", "Track stock levels and reorder on time", "Lose sales"]'::jsonb,2,'Systems track inventory.','original'),
('127.300.d.5.D',3,'A memorandum differs from a business letter because it is usually:','["Handwritten", "Sent to the press", "Sent to customers", "Sent inside an organization"]'::jsonb,3,'Memos are internal.','original'),
('127.300.d.5.D',4,'A professional email to a customer should include:','["A clear subject line and polite greeting", "No greeting", "Slang", "All capital letters"]'::jsonb,0,'Format shows professionalism.','original'),
('127.300.d.5.E',3,'Applying entrepreneurship processes to grow a business could include:','["Stopping all marketing", "Researching a new market for the product", "Closing the shop", "Reducing quality"]'::jsonb,1,'Growth requires research.','original'),
('127.300.d.5.E',4,'Adding a second product line to reach new customers is a:','["Tax strategy", "Retirement plan", "Growth strategy", "Failure sign"]'::jsonb,2,'New lines grow revenue.','original'),
('127.300.d.5.F',3,'Growth in technical skill competencies appears when a student:','["Makes more errors", "Avoids tasks", "Needs more help each time", "Performs tasks more independently and accurately over time"]'::jsonb,3,'Independence shows growth.','original'),
('127.300.d.5.F',4,'A student rates skills in September and again in March to see:','["Progress over the practicum", "Weather changes", "Nothing", "Price changes"]'::jsonb,0,'Comparing ratings shows growth.','original'),
('127.300.d.5.G',4,'A student is strong at selling but weak at bookkeeping. A smart step is to:','["Hide the weakness", "Seek training in bookkeeping", "Avoid bookkeeping", "Stop selling"]'::jsonb,1,'Address weak areas.','original'),
('127.300.d.5.H',3,'Which item is a good work sample for an entrepreneurship portfolio?','["A grocery list", "A recipe", "A business plan section you wrote", "A game score"]'::jsonb,2,'Samples show relevant skills.','original'),
